<?php
namespace Database\Seeders;use App\Models\InsightRule;use Illuminate\Database\Seeder;
class InsightRuleSeeder extends Seeder{public function run():void{$rules=[['RF-001','Possible coverage problem','coverage','high',['median_rssi_lte'=>-75,'minimum_measurements'=>10],'Possible coverage problem detected.','Review AP placement and conduct a controlled follow-up survey.','Congestion cannot be excluded without AP-load telemetry.'],['PERF-001','Performance degradation','performance','medium',['median_download_lt'=>10,'minimum_tests'=>5],'Low throughput detected during the selected period.','Investigate capacity, uplink, interference and application demand before assigning a cause.','Low throughput alone does not identify root cause.'],['UX-001','Correlated user experience decline','feedback','medium',['minimum_correlated_complaints'=>3],'User reports align with technical evidence from this location and period.','Review the corresponding measurements and prioritize a follow-up survey.','Correlation does not prove a single cause.']];foreach($rules as[$code,$name,$category,$severity,$conditions,$conclusion,$recommendation,$default_limitation])InsightRule::updateOrCreate(['code'=>$code],compact('name','category','severity','conditions','conclusion','recommendation','default_limitation'));}}
